def VTask.replaceVertex {V : Type u_1} (G : SimpleGraph V) (s t : V) [DecidableEq V] : SimpleGraph V :=
let sNeighbors := G.Adj s - {t}
let tNeighbors := G.Adj t - {s}
let newEdges := G.EdgeSet.filter fun e => e.1 ≠ t ∧ e.2 ≠ t ∨ e.1 = s ∧ e.2 ∈ sNeighbors ∨ e.2 = s ∧ e.1 ∈ sNeighbors ∨ e.1 = t ∧ e.2 ∈ tNeighbors ∨ e.2 = t ∧ e.1 ∈ tNeighbors
SimpleGraph.ofEdgeList G.VertexSet newEdges
